using System.Diagnostics;
using System.Net.Security;
using System.Net.Sockets;
using System.Security.Authentication;
using System.Security.Cryptography.X509Certificates;
namespace Charker;
public static class TlsRegression {
 public static int RunCommand(){try{var r=Run().GetAwaiter().GetResult();File.WriteAllText(Path.Combine(AppContext.BaseDirectory,"tls-test-results.json"),JsonSerializer.Serialize(r,new JsonSerializerOptions{WriteIndented=true}));return 0;}catch(Exception e){File.WriteAllText(Path.Combine(AppContext.BaseDirectory,"tls-test-results.json"),JsonSerializer.Serialize(new{ok=false,error=e.ToString()},new JsonSerializerOptions{WriteIndented=true}));return 1;}}
 static X509Certificate2 Leaf(string name,RSA key,X509Certificate2 root,bool server){var request=new CertificateRequest("CN="+name,key,HashAlgorithmName.SHA256,RSASignaturePadding.Pkcs1);request.CertificateExtensions.Add(new X509BasicConstraintsExtension(false,false,0,true));request.CertificateExtensions.Add(new X509KeyUsageExtension(X509KeyUsageFlags.DigitalSignature,true));request.CertificateExtensions.Add(new X509EnhancedKeyUsageExtension(new OidCollection{new(server?"1.3.6.1.5.5.7.3.1":"1.3.6.1.5.5.7.3.2")},true));if(server){var san=new SubjectAlternativeNameBuilder();san.AddDnsName("localhost");request.CertificateExtensions.Add(san.Build());}using var issued=request.Create(root,DateTimeOffset.UtcNow.AddMinutes(-5),DateTimeOffset.UtcNow.AddHours(2),RandomNumberGenerator.GetBytes(16));return issued.CopyWithPrivateKey(key);}
 static async Task<object> Run(){using var timeout=new CancellationTokenSource(TimeSpan.FromSeconds(45));var ct=timeout.Token;
  using var caKey=RSA.Create(2048);var caRequest=new CertificateRequest("CN=Charker loopback test CA",caKey,HashAlgorithmName.SHA256,RSASignaturePadding.Pkcs1);caRequest.CertificateExtensions.Add(new X509BasicConstraintsExtension(true,false,0,true));caRequest.CertificateExtensions.Add(new X509KeyUsageExtension(X509KeyUsageFlags.KeyCertSign|X509KeyUsageFlags.CrlSign,true));using var root=caRequest.CreateSelfSigned(DateTimeOffset.UtcNow.AddMinutes(-10),DateTimeOffset.UtcNow.AddDays(1));
  using var serverKey=RSA.Create(2048);using var clientKey=RSA.Create(2048);using var serverCert=Leaf("localhost",serverKey,root,true);using var clientCert=Leaf("Charker test client",clientKey,root,false);
  var start=NodeTlsStream.StartInfo();start.ArgumentList.Add("--test-server");using var process=new Process{StartInfo=start,EnableRaisingEvents=true};var listening=new TaskCompletionSource<int>(TaskCreationOptions.RunContinuationsAsynchronously);int authorized=0;
  process.ErrorDataReceived+=(_,e)=>{try{var m=JsonNode.Parse(e.Data??"null");if(m?["event"]?.ToString()=="listening")listening.TrySetResult((int)m["port"]!);if(m?["event"]?.ToString()=="peer"&&(bool?)m["authorized"]==true)Interlocked.Increment(ref authorized);if(m?["event"]?.ToString()=="error")listening.TrySetException(new IOException("Test server: "+m["code"]));}catch(JsonException){}};
  try{process.Start();process.BeginErrorReadLine();await process.StandardInput.WriteLineAsync(JsonSerializer.Serialize(new{cert=serverCert.ExportCertificatePem(),key=serverKey.ExportPkcs8PrivateKeyPem(),ca=root.ExportCertificatePem()}));int port=await listening.Task.WaitAsync(TimeSpan.FromSeconds(10),ct);
   // Pin only this generated server in the legacy reproduction; no global trust changes.
   bool legacyFailed=false;var legacyCodes=new List<string>();try{using var tcp=new TcpClient();await tcp.ConnectAsync("127.0.0.1",port,ct);using var legacy=new SslStream(tcp.GetStream(),false,(_,c,_,_)=>c!=null&&CryptographicOperations.FixedTimeEquals(c.GetRawCertData(),serverCert.RawData));using var pem=X509Certificate2.CreateFromPem(clientCert.ExportCertificatePem(),clientKey.ExportPkcs8PrivateKeyPem());await legacy.AuthenticateAsClientAsync(new SslClientAuthenticationOptions{TargetHost="localhost",ClientCertificates=new X509CertificateCollection{pem},EnabledSslProtocols=SslProtocols.Tls12},ct).WaitAsync(TimeSpan.FromSeconds(8),ct);}
   catch(Exception e){legacyFailed=true;for(Exception? inner=e;inner!=null;inner=inner.InnerException)legacyCodes.Add(inner.GetType().Name+" 0x"+inner.HResult.ToString("X8"));}
   var results=new List<string>();using(var relay=await NodeTlsStream.Connect("127.0.0.1",clientCert.ExportCertificatePem(),clientKey.ExportPkcs8PrivateKeyPem(),ct,port,root.ExportCertificatePem(),"localhost")){byte[] expected=[0,1,2,0xff,0x30,0,128,255];await relay.WriteAsync(expected,ct);byte[] actual=new byte[expected.Length];await relay.ReadExactlyAsync(actual,ct).AsTask().WaitAsync(TimeSpan.FromSeconds(5),ct);if(!actual.SequenceEqual(expected))throw new IOException("Binary TLS relay corrupted data");results.Add("PASS Windows in-memory PEM mutual TLS and binary stream round-trip");}
   bool rejected=false;try{using var bad=await NodeTlsStream.Connect("127.0.0.1",clientCert.ExportCertificatePem(),clientKey.ExportPkcs8PrivateKeyPem(),ct,port,root.ExportCertificatePem(),"wrong-host.invalid");}catch(IOException){rejected=true;}if(!rejected)throw new Exception("Hostname mismatch was not rejected");results.Add("PASS Wrong server name rejected");
   using var otherKey=RSA.Create(2048);using var untrusted=new CertificateRequest("CN=Untrusted test CA",otherKey,HashAlgorithmName.SHA256,RSASignaturePadding.Pkcs1).CreateSelfSigned(DateTimeOffset.UtcNow.AddMinutes(-1),DateTimeOffset.UtcNow.AddHours(1));rejected=false;try{using var bad=await NodeTlsStream.Connect("127.0.0.1",clientCert.ExportCertificatePem(),clientKey.ExportPkcs8PrivateKeyPem(),ct,port,untrusted.ExportCertificatePem(),"localhost");}catch(IOException){rejected=true;}if(!rejected)throw new Exception("Untrusted issuer was not rejected");results.Add("PASS Untrusted certificate issuer rejected");
   using(var stalled=new TcpListener(System.Net.IPAddress.Loopback,0)){stalled.Start();using var budget=new CancellationTokenSource(250);var clock=Stopwatch.StartNew();bool cancelled=false;try{using var relay=await NodeTlsStream.Connect("127.0.0.1",clientCert.ExportCertificatePem(),clientKey.ExportPkcs8PrivateKeyPem(),budget.Token,((System.Net.IPEndPoint)stalled.LocalEndpoint).Port,root.ExportCertificatePem(),"localhost");}catch(OperationCanceledException){cancelled=true;}if(!cancelled||clock.Elapsed>TimeSpan.FromSeconds(2))throw new Exception("Stalled TLS handshake ignored cancellation");results.Add("PASS Stalled TLS handshake cancels promptly and closes its relay");}
   return new{ok=true,legacySchannelFailureReproduced=legacyFailed,legacyErrors=legacyCodes,authorizedClientSessions=authorized,results};
  }finally{if(process.Id!=0){try{process.StandardInput.Close();if(!process.WaitForExit(2000))process.Kill(true);}catch(InvalidOperationException){}}}
 }
}
